import { randomUUID } from "node:crypto";
import { and, eq, gt, inArray, lte, sql } from "drizzle-orm";
import { getDb } from "@/db";
import { videoUploadSessions } from "@/db/schema";
import { enqueueStorageCleanupTx } from "@/lib/storage-cleanup";
import { normalizeStorageKey, storageUploadLimitBytes } from "@/lib/storage-policy";
import { VIDEO_PART_BYTES, VIDEO_UPLOAD_TYPES, UPLOAD_UUID, validateVideoManifest, videoPartSize, type MultipartUploadView } from "@/lib/video-upload-policy";
import { startMultipartUpload, signMultipartPart, listMultipartParts, completeMultipartUpload, headMultipartUpload, multipartCompositeChecksum, abortMultipartUpload, type UploadedPart } from "@/lib/railway-direct-upload";

type Session = typeof videoUploadSessions.$inferSelect;
type Tx = Parameters<Parameters<ReturnType<typeof getDb>["transaction"]>[0]>[0];
type UploadInput = { clientRequestId: string; courseSlug: string; lessonId: string; contentType: string; sizeBytes: number; checksums: string[] };
export class VideoUploadError extends Error {
  constructor(message: string, public status = 409) { super(message); this.name = "VideoUploadError"; }
}
function checksums(session: Session): string[] {
  const values: unknown = JSON.parse(session.checksumsJson);
  validateVideoManifest(session.sizeBytes, values);
  return values;
}
function live(session: Session) {
  if (session.status === "aborted" || session.status !== "finalized" && session.expiresAt.getTime() <= Date.now()) throw new VideoUploadError("انتهت جلسة الرفع؛ ابدأ جلسة جديدة.", 410);
}
function view(session: Session, completedParts: number[] = []): MultipartUploadView {
  return { id: session.id, objectKey: session.objectKey, courseSlug: session.courseSlug, lessonId: session.lessonId,
    contentType: session.contentType, sizeBytes: session.sizeBytes, partSize: VIDEO_PART_BYTES,
    status: session.status, expiresAt: session.expiresAt.toISOString(), completedParts };
}
async function owned(tx: Tx, id: string, userId: number) {
  if (!UPLOAD_UUID.test(id) || !Number.isSafeInteger(userId) || userId < 1) throw new VideoUploadError("جلسة الرفع غير موجودة.", 404);
  const [session] = await tx.select().from(videoUploadSessions).where(and(eq(videoUploadSessions.id, id), eq(videoUploadSessions.userId, userId))).for("update");
  if (!session) throw new VideoUploadError("جلسة الرفع غير موجودة.", 404);
  live(session); return session;
}
function validParts(session: Session, parts: UploadedPart[]) {
  const expected = checksums(session), seen = new Set<number>();
  for (const part of parts) {
    if (seen.has(part.partNumber) || part.size !== videoPartSize(session.sizeBytes, part.partNumber)
        || part.checksum !== expected[part.partNumber - 1]) throw new VideoUploadError("حجم أو بصمة جزء مخزن لا يطابق الملف المختار.", 422);
    seen.add(part.partNumber);
  }
  return [...parts].sort((a, b) => a.partNumber - b.partNumber);
}
async function completedObject(session: Session, signal?: AbortSignal) {
  const object = await headMultipartUpload(session.objectKey, signal);
  if (!object) return false;
  if (object.sessionId !== session.id || object.size !== session.sizeBytes || object.contentType !== session.contentType
      || object.checksum !== multipartCompositeChecksum(checksums(session))) throw new VideoUploadError("تعذر إثبات سلامة الملف المكتمل.", 422);
  return true;
}

export async function startVideoUpload(userId: number, input: UploadInput, signal?: AbortSignal) {
  if (!UPLOAD_UUID.test(input.clientRequestId) || !Number.isSafeInteger(userId) || userId < 1
      || !VIDEO_UPLOAD_TYPES.includes(input.contentType as typeof VIDEO_UPLOAD_TYPES[number])) throw new VideoUploadError("بيانات الرفع غير صالحة.", 400);
  validateVideoManifest(input.sizeBytes, input.checksums);
  if (input.sizeBytes > storageUploadLimitBytes(process.env.STORAGE_MAX_UPLOAD_BYTES)) throw new VideoUploadError("حجم الملف أكبر من حد التخزين.", 413);
  const path = normalizeStorageKey(`private/video-source/${input.courseSlug}/${input.lessonId}`);
  if (path !== `private/video-source/${input.courseSlug}/${input.lessonId}` || !input.courseSlug || !input.lessonId || input.courseSlug.includes("/") || input.lessonId.includes("/")) throw new VideoUploadError("مسار الدرس غير صالح.", 400);
  let remote: { key: string; uploadId: string } | undefined;
  try {
    return await getDb().transaction(async tx => {
      // Serializes admission across servers, not just within one Node process.
      await tx.execute(sql`SELECT pg_advisory_xact_lock(hashtext(${`video-upload-owner:${userId}`}))`);
      const [previous] = await tx.select().from(videoUploadSessions).where(and(eq(videoUploadSessions.userId, userId), eq(videoUploadSessions.clientRequestId, input.clientRequestId))).for("update");
      if (previous) {
        if (previous.courseSlug !== input.courseSlug || previous.lessonId !== input.lessonId || previous.contentType !== input.contentType
            || previous.sizeBytes !== input.sizeBytes || previous.checksumsJson !== JSON.stringify(input.checksums)) throw new VideoUploadError("معرّف الاستئناف يخص ملفًا مختلفًا.");
        live(previous); return view(previous);
      }
      const active = await tx.select({ id: videoUploadSessions.id }).from(videoUploadSessions).where(and(eq(videoUploadSessions.userId, userId),
        inArray(videoUploadSessions.status, ["uploading", "uploaded"]), gt(videoUploadSessions.expiresAt, new Date()))).limit(3);
      if (active.length >= 3) throw new VideoUploadError("لديك ثلاث جلسات رفع مفتوحة؛ أكملها أو ألغِ إحداها.", 429);
      const id = randomUUID(), extension = ({ "video/mp4": "mp4", "video/webm": "webm", "video/quicktime": "mov", "video/x-matroska": "mkv", "video/x-msvideo": "avi" } as Record<string, string>)[input.contentType];
      const objectKey = `${path}/mp-${id}.${extension}`;
      const uploadId = await startMultipartUpload(objectKey, input.contentType, id, signal);
      remote = { key: objectKey, uploadId };
      const [session] = await tx.insert(videoUploadSessions).values({ id, userId, clientRequestId: input.clientRequestId,
        courseSlug: input.courseSlug, lessonId: input.lessonId, objectKey, contentType: input.contentType, sizeBytes: input.sizeBytes,
        checksumsJson: JSON.stringify(input.checksums), uploadId, expiresAt: new Date(Date.now() + 86_400_000) }).returning();
      return view(session);
    });
  } catch (error) {
    // S3 and PostgreSQL cannot commit atomically. Bucket AbortIncompleteMultipartUpload
    // lifecycle is mandatory for the crash window before the upload ID is saved.
    if (remote) await abortMultipartUpload(remote.key, remote.uploadId).catch(() => undefined);
    throw error;
  }
}

export async function getVideoUpload(userId: number, id: string, signal?: AbortSignal) {
  return getDb().transaction(async tx => {
    const session = await owned(tx, id, userId);
    if (session.status !== "uploading") return view(session);
    const parts = await listMultipartParts(session.objectKey, session.uploadId!, signal);
    if (parts === null) {
      // A successful S3 completion followed by a lost database acknowledgement is recoverable.
      if (!await completedObject(session, signal)) throw new VideoUploadError("جلسة التخزين لم تعد موجودة؛ ابدأ رفعًا جديدًا.", 410);
      const [saved] = await tx.update(videoUploadSessions).set({ status: "uploaded", updatedAt: new Date() }).where(eq(videoUploadSessions.id, id)).returning();
      return view(saved);
    }
    return view(session, validParts(session, parts).map(part => part.partNumber));
  });
}

export async function signVideoUploadPart(userId: number, id: string, partNumber: number) {
  return getDb().transaction(async tx => {
    const session = await owned(tx, id, userId);
    if (session.status !== "uploading") throw new VideoUploadError("الرفع مكتمل ولا يقبل أجزاء جديدة.");
    const size = videoPartSize(session.sizeBytes, partNumber);
    const remaining = Math.floor((session.expiresAt.getTime() - Date.now()) / 1000);
    if (remaining < 60) throw new VideoUploadError("انتهت مهلة إصدار أجزاء جديدة.", 410);
    return signMultipartPart(session.objectKey, session.uploadId!, partNumber, size, checksums(session)[partNumber - 1], Math.min(300, remaining));
  });
}

export async function completeVideoUpload(userId: number, id: string, signal?: AbortSignal) {
  return getDb().transaction(async tx => {
    const session = await owned(tx, id, userId);
    if (session.status === "finalized" || session.status === "uploaded") return view(session);
    if (!await completedObject(session, signal)) {
      const stored = await listMultipartParts(session.objectKey, session.uploadId!, signal);
      if (!stored) throw new VideoUploadError("أجزاء الملف غير متاحة؛ ابدأ جلسة جديدة.", 410);
      const parts = validParts(session, stored);
      if (parts.length !== checksums(session).length) throw new VideoUploadError("بعض أجزاء الملف لم تكتمل بعد.");
      try { await completeMultipartUpload(session.objectKey, session.uploadId!, parts, session.sizeBytes, signal); }
      catch (error) { if (!await completedObject(session, signal)) throw error; }
      if (!await completedObject(session, signal)) throw new VideoUploadError("التخزين لم يؤكد اكتمال الملف بعد.");
    }
    const [saved] = await tx.update(videoUploadSessions).set({ status: "uploaded", updatedAt: new Date() }).where(eq(videoUploadSessions.id, id)).returning();
    return view(saved);
  });
}

async function retireTx(tx: Tx, session: Session) {
  if (session.status === "finalized" || session.status === "aborted") return;
  await enqueueStorageCleanupTx(tx, [{ key: session.objectKey, source: "video-upload", provider: "s3",
    ...(session.uploadId ? { uploadId: session.uploadId } : {}) }]);
  await tx.update(videoUploadSessions).set({ status: "aborted", updatedAt: new Date() }).where(eq(videoUploadSessions.id, session.id));
}
export async function abortVideoUpload(userId: number, id: string) {
  if (!UPLOAD_UUID.test(id)) throw new VideoUploadError("جلسة الرفع غير موجودة.", 404);
  await getDb().transaction(async tx => {
    const [session] = await tx.select().from(videoUploadSessions).where(and(eq(videoUploadSessions.id, id), eq(videoUploadSessions.userId, userId))).for("update");
    if (!session) throw new VideoUploadError("جلسة الرفع غير موجودة.", 404);
    if (session.status === "finalized") throw new VideoUploadError("الفيديو مرتبط بالدرس؛ استخدم حذف الفيديو بدل إلغاء الرفع.");
    await retireTx(tx, session);
  });
}
export async function expireVideoUploads() {
  return getDb().transaction(async tx => {
    const expired = await tx.select().from(videoUploadSessions).where(and(inArray(videoUploadSessions.status, ["uploading", "uploaded"]),
      lte(videoUploadSessions.expiresAt, new Date()))).limit(20).for("update", { skipLocked: true });
    for (const session of expired) await retireTx(tx, session);
    return expired.length;
  });
}
export async function retireOwnerVideoUploadsTx(tx: Tx, userId: number) {
  const sessions = await tx.select().from(videoUploadSessions).where(eq(videoUploadSessions.userId, userId)).for("update");
  for (const session of sessions) await retireTx(tx, session);
  await tx.delete(videoUploadSessions).where(eq(videoUploadSessions.userId, userId));
}

/** Called twice: authorization before storage reads, then again under the finalization transaction lock. */
export async function lockVideoUploadReceiptTx(tx: Tx, userId: number, id: string, expected: { objectKey: string; courseSlug: string; lessonId: string; sizeBytes: number; contentType: string }) {
  const session = await owned(tx, id, userId);
  if (session.status !== "uploaded" && session.status !== "finalized") throw new VideoUploadError("أكمل أجزاء الرفع أولًا.");
  for (const key of ["objectKey", "courseSlug", "lessonId", "sizeBytes", "contentType"] as const) {
    if (session[key] !== expected[key]) throw new VideoUploadError("إيصال الرفع لا يطابق هذا الفيديو.", 403);
  }
  return session;
}
export async function finalizeVideoUploadReceiptTx(tx: Tx, id: string, assetId: number) {
  await tx.update(videoUploadSessions).set({ status: "finalized", assetId, updatedAt: new Date() }).where(eq(videoUploadSessions.id, id));
}
